7	/* Reference model: a flat array of key/value pairs, kept in sync with the
8	 * tree on every successful insert. Linear scans are fine here — this is a
9	 * correctness oracle, not something that needs to be fast. */
10	struct model_entry {
11	    char *key;
12	    int  *value;
13	};
14	
15	struct model {
16	    struct model_entry *entries;
17	    size_t               count;
18	    size_t               capacity;
19	};
20	
21	static void model_init(struct model *m) {
22	    m->entries = NULL;
23	    m->count = 0;
24	    m->capacity = 0;
25	}
26	
27	static struct model_entry *model_find(struct model *m, const char *key) {
28	    for (size_t i = 0; i < m->count; i++) {
29	        if (strcmp(m->entries[i].key, key) == 0) return &m->entries[i];
30	    }
31	    return NULL;
32	}
33	
34	static void model_put(struct model *m, const char *key, int *value) {
35	    struct model_entry *e = model_find(m, key);
36	    if (e != NULL) {
37	        free(e->value);
38	        e->value = value;
39	        return;
40	    }
41	    if (m->count == m->capacity) {
42	        size_t new_cap = m->capacity == 0 ? 64 : m->capacity * 2;
43	        struct model_entry *grown = realloc(m->entries, new_cap * sizeof *grown);
44	        if (grown == NULL) { fprintf(stderr, "fuzz: model realloc failed\n"); exit(1); }
45	        m->entries = grown;
46	        m->capacity = new_cap;
47	    }
48	    m->entries[m->count].key = strdup(key);
49	    if (m->entries[m->count].key == NULL) { fprintf(stderr, "fuzz: strdup failed\n"); exit(1); }
50	    m->entries[m->count].value = value;
51	    m->count++;
52	}
53	
54	static void model_destroy(struct model *m) {
55	    for (size_t i = 0; i < m->count; i++) {
56	        free(m->entries[i].key);
57	        free(m->entries[i].value);
58	    }
59	    free(m->entries);
60	}
61	
62	static void make_key(char *buf, size_t buflen, unsigned key_space) {
63	    snprintf(buf, buflen, "key%06u", (unsigned)(rand() % key_space));
64	}
65	
66	int main(int argc, char **argv) {
67	    long op_count = argc > 1 ? atol(argv[1]) : 100000;
68	    unsigned seed = argc > 2 ? (unsigned)atol(argv[2]) : (unsigned)time(NULL);
69	    unsigned key_space = 5000;
70	    srand(seed);
71	    printf("fuzz: seed=%u op_count=%ld\n", seed, op_count);
72	
73	    rbtree_t *t = rb_create(NULL);
74	    if (t == NULL) { fprintf(stderr, "fuzz: rb_create failed\n"); return 1; }
75	
76	    struct model m;
77	    model_init(&m);
78	
79	    char keybuf[32];
80	    for (long op = 0; op < op_count; op++) {
81	        make_key(keybuf, sizeof keybuf, key_space);
82	        int choose_insert = rand() % 2;
83	
84	        if (choose_insert) {
85	            int *value = malloc(sizeof *value);
86	            if (value == NULL) { fprintf(stderr, "fuzz: value malloc failed\n"); return 1; }
87	            *value = (int)op;
88	
89	            int rc = rb_insert(t, keybuf, value);
90	            if (rc != 0) {
91	                fprintf(stderr, "fuzz: rb_insert failed unexpectedly at op %ld\n", op);
92	                free(value);
93	                return 1;
94	            }
95	            void *found = rb_find(t, keybuf);
96	            if (found != value) {
97	                fprintf(stderr, "fuzz: rb_find after insert mismatch at op %ld "
98	                                 "(key=%s)\n", op, keybuf);
99	                return 1;
100	            }
101	            model_put(&m, keybuf, value);
102	        } else {
103	            struct model_entry *e = model_find(&m, keybuf);
104	            void *found = rb_find(t, keybuf);
105	            if (e == NULL) {
106	                if (found != NULL) {
107	                    fprintf(stderr, "fuzz: rb_find found a key the model doesn't have "
108	                                     "at op %ld (key=%s)\n", op, keybuf);
109	                    return 1;
110	                }
111	            } else if (found != e->value) {
112	                fprintf(stderr, "fuzz: rb_find value mismatch at op %ld (key=%s)\n",
113	                        op, keybuf);
114	                return 1;
115	            }
116	        }
117	
118	        if (op % 100 == 0) {
119	            int rc = rb_validate(t);
120	            if (rc != 0) {
121	                fprintf(stderr, "fuzz: rb_validate failed at op %ld (invariant %d)\n",
122	                        op, rc);
123	                return 1;
124	            }
125	        }
126	
127	        if (rb_size(t) != m.count) {
128	            fprintf(stderr, "fuzz: rb_size (%zu) != model count (%zu) at op %ld\n",
129	                    rb_size(t), m.count, op);
130	            return 1;
131	        }
132	    }
133	
